export const k8sUpdateCommand = defineCommand({
  description: 'Update the settings of a Kubernetes cluster',
  since: null,
  options: {
    name: defineOption({
      name: 'name',
      schema: z.string().optional(),
      description: 'Set the cluster name',
      placeholder: 'name',
    }),
    description: defineOption({
      name: 'description',
      schema: z.string().max(4096).optional(),
      description: 'Set the free-form cluster description',
      placeholder: 'description',
    }),
    tag: defineOption({
      name: 'tag',
      schema: z.string().transform(tags).optional(),
      description: 'Replace the semantic tags (comma-separated, e.g.: env:prod,team:platform)',
      placeholder: 'tag[,tag...]',
    }),
    enableAutoscaling: defineOption({
      name: 'enable-autoscaling',
      schema: z.boolean().default(false),
      description: 'Enable the cluster autoscaler',
    }),
    disableAutoscaling: defineOption({
      name: 'disable-autoscaling',
      schema: z.boolean().default(false),
      description: 'Disable the cluster autoscaler',
    }),
    org: orgaIdOrNameOption,
  },
  args: [k8sIdOrNameArg],
  async handler(options, clusterIdOrName) {
    if (options.enableAutoscaling && options.disableAutoscaling) {
      throw new Error('--enable-autoscaling and --disable-autoscaling are mutually exclusive');
    }

    const updates = {};
    if (options.name != null) updates.name = options.name;
    if (options.description != null) updates.description = options.description;
    if (options.tag != null) updates.tags = options.tag;
    if (options.enableAutoscaling) updates.features = { autoscalingEnabled: true };
    if (options.disableAutoscaling) updates.features = { autoscalingEnabled: false };

    if (Object.keys(updates).length === 0) {
      throw new Error('No setting to update');
    }

    const cluster = await k8sUpdate(options.org, clusterIdOrName, updates);

    Logger.printSuccess(`Cluster ${styleText('green', `${cluster.name} (${cluster.id})`)} updated`);
  },
});
